import neo4j

def unit_of_work(metadata=None, timeout=None):
    def decorate(func):
        def wrapper(func_obj, *args, **kwargs):
            # Create a decorator function that will wrap the original function
            def decorated(*args, **kwargs):
                # Use the unit of work context manager
                driver = func_obj.driver if hasattr(func_obj, 'driver') else None
                if driver is None:
                    raise ValueError("No driver available")

                with driver.session() as session:
                    # Apply the unit of work with specified metadata and timeout
                    @neo4j.unit_of_work(metadata=metadata, timeout=timeout)
                    def inner_tx(tx):
                        # Call the original function with the transaction
                        return func(tx)

                    session.write_transaction(inner_tx)
            return decorated
        return wrapper
    return decorate

