def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """

    def decorator(func):

        @functools.wraps(func)
        def memoized(*args, **kwargs):
            k = key(args, kwargs, func, cache)
            if lock is not None:
                with lock:
                    res = cache.get_value(k)
            else:
                res = cache.get_value(k)
            if res is None:
                res = func(*args, **kwargs)
                cache.put_value(k, res)
            return res

        return memoized

    return decorator
