def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from functools import wraps
    from collections import defaultdict

    def decorator(func):
        cache = {}  # key -> value
        freq = defaultdict(int)  # key -> frequency
        freq_map = defaultdict(set)  # freq -> set of keys

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal cache, freq, freq_map

            # Create a hashable key
            try:
                key = (args, frozenset(kwargs.items()))
            except TypeError:
                # If args contains unhashable types, we can't cache (fallback to direct call)
                return func(*args, **kwargs)

            # Normalize the key if 'typed' is True
            if typed:
                def make_normal(arg):
                    if type(arg) is int and not isinstance(arg, bool):
                        return 'i', arg
                    elif type(arg) is float:
                        return 'f', arg
                    elif type(arg) is str:
                        return 's', arg
                    elif type(arg) is bytes:
                        return 'b', arg
                    elif type(arg) is tuple:
                        return 't', tuple(make_normal(a) for a in arg)
                    elif type(arg) is list:
                        return 'l', tuple(make_normal(a) for a in arg)
                    else:
                        return 'o', (id(type(arg)),) # Fallback for other objects
                try:
                    key = (tuple(make_normal(a) for a in args), tuple(sorted((k, make_normal(v)) for k, v in kwargs.items())))
                except Exception:
                    # Fallback if normalization fails
                    return func(*args, **kwargs)

            # Check if key is in cache
            if key in cache:
                # Increase frequency
                old_freq = freq[key]
                freq_map[old_freq].discard(key)
                if not freq_map[old_freq]:
                    del freq_map[old_freq]

                new_freq = old_freq + 1
                freq[key] = new_freq
                freq_map[new_freq].add(key)

                return cache[key]

            # Call the function
            result = func(*args, **kwargs)

            # Check if we need to evict an item
            if len(cache) >= maxsize:
                # Find the least frequent key
                min_freq = min(freq_map)
                # If multiple keys have the same min freq, we just pick one (arbitrary, as LRU would use time)
                # To make it deterministic, we could use a set and pick one, but order is not guaranteed in sets.
                # However, standard LFU implementations often don't require strict FIFO among same frequency levels 
                # unless specified. Let's just pop one.
                if freq_map[min_freq]:
                    evict_key = next(iter(freq_map[min_freq]))
                    freq_map[min_freq].discard(evict_key)
                    if not freq_map[min_freq]:
                        del freq_map[min_freq]

                    del cache[evict_key]
                    del freq[evict_key]

            # Add new item
            cache[key] = result
            freq[key] = 1
            freq_map[1].add(key)

            return result

        wrapper.cache = cache
        wrapper.freq = freq
        wrapper.freq_map = freq_map
        wrapper.cache_info = lambda: hits=0, misses=0, maxsize=maxsize, currsize=len(cache) # Placeholder for cache_info

        # Proper cache_info
        hits = 0
        misses = 0
        def _cache_info():
            return f'LFU(cache_hits={hits}, cache_misses={misses}, maxsize={maxsize}, currsize={len(cache)})'
        wrapper.__wrapped__ = func
        wrapper.__defaults__ = (maxsize, typed)

        # Redefine wrapper to track hits/misses properly
        @wraps(func)
        def inner_wrapper(*args, **kwargs):
            nonlocal hits, misses
            try:
                key = (args, frozenset(kwargs.items()))
            except TypeError:
                misses += 1
                return func(*args, **kwargs)

            if typed:
                def make_normal(arg):
                    if type(arg) is int and not isinstance(arg, bool):
                        return 'i', arg
                    elif type(arg) is float:
                        return 'f', arg
                    elif type(arg) is str:
                        return 's', arg
                    elif type(arg) is bytes:
                        return 'b', arg
                    elif type(arg) is tuple:
                        return 't', tuple(make_normal(a) for a in arg)
                    elif type(arg) is list:
                        return 'l', tuple(make_normal(a) for a in arg)
                    else:
                        return 'o', (id(type(arg)),) 
                try:
                    key = (tuple(make_normal(a) for a in args), tuple(sorted((k, make_normal(v)) for k, v in kwargs.items())))
                except Exception:
                    misses += 1
                    return func(*args, **kwargs)

            if key in cache:
                hits += 1
                old_freq = freq[key]
                freq_map[old_freq].discard(key)
                if not freq_map[old_freq]:
                    del freq_map[old_freq]

                new_freq = old_freq + 1
                freq[key] = new_freq
                freq_map[new_freq].add(key)

                return cache[key]

            misses += 1
            result = func(*args, **kwargs)

            if len(cache) >= maxsize:
                min_freq = min(freq_map)
                if freq_map[min_freq]:
                    evict_key = next(iter(freq_map[min_freq]))
                    freq_map[min_freq].discard(evict_key)
                    if not freq_map[min_freq]:
                        del freq_map[min_freq]

                    del cache[evict_key]
                    del freq[evict_key]

            cache[key] = result
            freq[key] = 1
            freq_map[1].add(key)

            return result

        inner_wrapper.cache_info = _cache_info
        inner_wrapper.__wrapped__ = func
        return inner_wrapper
    return decorator

