def directlyProvidedBy(object):
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # Retrieve the __provides__ attribute if it exists
    provides = getattr(object, '__provides__', None)
    if provides is not None:
        # If it's already a Declaration, wrap it to ensure we return a proper IDeclaration
        import zope.interface
        if isinstance(provides, zope.interface.interfaces.IDeclaration):
            return zope.interface.Declaration(provides)
        else:
            # For non-declaration interfaces, wrap in a Declaration
            return zope.interface.Declaration(provides)

    # If __provides__ does not exist, create an empty Declaration
    import zope.interface
    return zope.interface.Declaration()

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    result = []
    seen = set()

    for cls in classes:
        # Skip if we haven't seen this class before
        if cls not in seen:
            seen.add(cls)
            # Remove any existing classes in result that are subclasses of cls
            new_result = []
            for existing in result:
                # Keep existing if cls is not a subclass of existing and existing is not a subclass of cls
                # We want to keep the most derived class (subclasses), so if existing is a subclass of cls, we remove existing
                # if existing is a subclass of cls, then cls is more general, so we should keep existing
                # Wait, we want the minimum bases. If we have [A, B] and B is a subclass of A, then [B] is sufficient.
                # So if existing is a subclass of cls, we keep existing and skip adding cls.
                # If cls is a subclass of existing, we remove existing (because cls is more specific).

                try:
                    if issubclass(existing, cls) and existing is not cls:
                        # existing is a subclass of cls, so cls is redundant - don't add cls
                        new_result.append(existing)
                    elif issubclass(cls, existing) and cls is not existing:
                        # cls is a subclass of existing, so existing is redundant - skip adding existing
                        continue
                    else:
                        # They are not in a subclass relationship, or they are the same
                        new_result.append(existing)
                except TypeError:
                    # This can happen if cls or existing are not classes (e.g., module or other non-class types)
                    # In that case, treat them as unrelated
                    new_result.append(existing)

            # Check if we should add cls
            should_add = True
            for existing in new_result:
                try:
                    if issubclass(existing, cls) and existing is not cls:
                        # existing is a subclass of cls, we already have something more specific, so don't add cls
                        should_add = False
                        break
                except TypeError:
                    pass

            if should_add:
                # Also remove any existing that are subclasses of cls (more general)
                # Wait, let me reconsider the logic.
                # Goal: keep the most specific classes. If A is a subclass of B, keep A, remove B.
                # So when adding cls:
                # 1. If any existing is a subclass of cls, then cls is less specific, skip adding
                # 2. If cls is a subclass of any existing, remove that existing
                # 3. Otherwise, add cls

                # Actually, let me redo this more carefully

                # Pass 1: Find if any existing is a subclass of cls
                any_subclass_of_cls = False
                new_result2 = []
                for existing in new_result:
                    try:
                        if issubclass(existing, cls) and existing is not cls:
                            any_subclass_of_cls = True
                            # Still keep existing for now, we'll handle removal later
                            new_result2.append(existing)
                        else:
                            new_result2.append(existing)
                    except TypeError:
                        new_result2.append(existing)

                # If any existing is a subclass of cls, don't add cls
                if not any_subclass_of_cls:
                    # Pass 2: Remove any existing that are supersubclass of cls (i.e., cls is subclass of existing)
                    final_result = []
                    for existing in new_result2:
                        try:
                            if issubclass(cls, existing) and cls is not existing:
                                # cls is more specific, remove existing
                                continue
                        except TypeError:
                            pass
                        final_result.append(existing)

                    # Add cls
                    result = final_result + [cls]
                else:
                    # cls is redundant, keep existing
                    result = new_result

    return result

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    attr_info = []
    for name in dir(self):
        if not all and name.startswith('_') and not hasattr(self, name):
            continue

        try:
            value = getattr(self, name)
        except AttributeError:
            continue

        if callable(value) or isinstance(value, (int, float, str, bool, bytes)) or value is None:
            attr_info.append((name, value))
    return sorted(attr_info, key=lambda x: x[0])

