def _validate_labels(labels):
    import re

    errors = []

    # Regex for valid label keys: 1-63 chars, alphanumeric or underscore, must start/end with alphanumeric
    key_pattern = r'^[a-zA-Z0-9][a-zA-Z0-9_]{0,61}[a-zA-Z0-9]$'
    # Regex for valid label values: 1-63 chars, alphanumeric, underscores, hyphens, slashes, colons, dots
    value_pattern = r'^[a-zA-Z0-9_\-/:.\ ]{0,63}$'

    if not isinstance(labels, dict):
        errors.append({
            'labels': 'expected a dictionary'
        })
        raise ValidationError([err for err in errors])

    for key, value in labels.items():
        # Check if key is a string
        if not isinstance(key, str):
            errors.append({
                str(key): 'expected string or bytes-like object'
            })
            continue

        # Check if key matches the pattern
        try:
            if not re.match(key_pattern, key):
                errors.append({
                    key: f"Label key '{key}' does not match the regex {key_pattern}"
                })
        except TypeError:
            errors.append({
                str(key): 'expected string or bytes-like object'
            })

        # Check if value is a string or list of strings
        if isinstance(value, str):
            try:
                if not re.match(value_pattern, value):
                    errors.append({
                        value: f"Label value '{value}' does not match the regex {value_pattern}"
                    })
            except TypeError:
                errors.append({
                    str(value): 'expected string or bytes-like object'
                })
        elif isinstance(value, (list, tuple)):
            for v in value:
                if not isinstance(v, str):
                    errors.append({
                        str(v): 'expected string or bytes-like object'
                    })
                    continue
                try:
                    if not re.match(value_pattern, v):
                        errors.append({
                            str(v): f"Label value '{v}' does not match the regex {value_pattern}"
