def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    if not isinstance(last_applied_manifest, dict):
        return

    if not isinstance(observer_schema, dict):
        return

    if not isinstance(response, dict):
        return

    # Iterate through the keys in observer_schema
    for key in observer_schema:
        # If the key is not in last_applied_manifest, set its value from response
        if key not in last_applied_manifest:
            # Check if the key exists in the response
            if key not in response:
                raise KeyError(f"Observed field '{key}' not present in Kubernetes response")
            last_applied_manifest[key] = response[key]
        else:
            # Recursively update nested dictionaries
            schema_value = observer_schema[key]
            manifest_value = last_applied_manifest[key]
            response_value = response.get(key)

            if isinstance(schema_value, dict) and isinstance(manifest_value, dict) and isinstance(response_value, dict):
                update_last_applied_manifest_dict_from_resp(manifest_value, schema_value, response_value)
            elif isinstance(schema_value, list) and isinstance(manifest_value, list) and isinstance(response_value, list):
                # Handle list case
                for i, item in enumerate(manifest_value):
                    if i < len(response_value):
                        if isinstance(item, dict) and isinstance(response_value[i], dict) and i < len(manifest_value):
                            # We need to update nested dictionaries in lists of dicts
                            if isinstance(schema_value[i], dict) if i < len(schema_value) else False:
                                update_last_applied_manifest_dict_from_resp(item, schema_value[i], response_value[i])
