def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    grouped = {}
    if not xmls:
        return grouped
    if not files:
        for xml in xmls:
            base_name = xml.rsplit('.', 1)[0] if '.' in xml else xml
            grouped[base_name] = {'source': source, 'files': []}
        return grouped
    for file_path in files:
        base_name = file_path.rsplit('.', 1)[0] if '.' in file_path else file_path
        if base_name in grouped:
            grouped[base_name]['files'].append(file_path)
        else:
            grouped[base_name] = {'source': source, 'files': [file_path]}
    for xml in xmls:
        base_name = xml.rsplit('.', 1)[0] if '.' in xml else xml
        if base_name not in grouped:
            grouped[base_name] = {'source': source, 'files': []}
    return grouped

