def find_path_type(path):
    import os

    try:
        # Check if path exists
        if not os.path.exists(path):
            return "error: path does not exist"

        # Check if it's a root (OCFL Storage Root) - typically has 0/root.spec
        if os.path.isfile(os.path.join(path, "0", "root.spec")):
            return "root"

        # Check if it's an object (OCFL Object) - has 0/object.yaml
        if os.path.isfile(os.path.join(path, "0", "object.yaml")):
            return "object"

        # Check if it's a file
        if os.path.isfile(path):
            return "file"

        # If it's a directory but doesn't match OCFL patterns
        if os.path.isdir(path):
            # Check if it has any 0/* files that might be inventory
            if os.path.exists(os.path.join(path, "0")):
                # Check if 0 directory contains any files that look like inventory
                zero_dir = os.path.join(path, "0")
                if os.path.isdir(zero_dir):
                    for item in os.listdir(zero_dir):
                        if item.endswith(('.yaml', '.yml')):
                            return "object"
            return "unknown directory type"

        # Fallback
        return "unknown path type"

    except Exception as e:
        return "error: {}".format(str(e))
