def size_to_bytes(size: str) -> int:
    if not isinstance(size, str):
        raise TypeError("size must be a string")

    size = size.strip()
    if not size:
        raise ValueError("size cannot be empty")

    # Check for valid formats
    try:
        # Try to parse as a number with optional suffix
        # Suffix can be K, M, G, T (uppercase or lowercase)

        # Remove the numeric part from the end
        numeric_part = size[:-1] if len(size) > 1 else size
        suffix = size[-1]

        # If the entire string is numeric
        if numeric_part == size:
            # No suffix, just a number
            return int(float(size))

        # Extract the numeric part and the suffix
        # The suffix must be K, M, G, or T
        if suffix not in 'kmgKMG':
            # Try to see if the entire string is a number
            return int(float(size))

        # The numeric part might have a decimal point
        numeric_value = float(numeric_part)

        # Handle the suffix
        if suffix in ('K', 'k'):
            return int(numeric_value * 1000)
        elif suffix in ('M', 'm'):
            return int(numeric_value * 1000 * 1000)
        elif suffix in ('G', 'g'):
            return int(numeric_value * 1000 * 1000 * 1000)
        elif suffix in ('T', 't'):
            return int(numeric_value * 1000 * 1000 * 1000 * 1000)
        else:
            return int(numeric_value)

    except ValueError:
        raise ValueError(f"Invalid size format: {size}")

