def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        return 0
    try:
        base = len(alphabet)
    except TypeError as e:
        raise e
    if base <= 0:
        raise ValueError("Alphabet must be non-empty")
    # Create a mapping from character to value for O(1) lookup
    char_to_value = {}
    for index, char in enumerate(alphabet):
        char_to_value[char] = index

    number = 0
    for char in string:
        if char not in char_to_value:
            raise ValueError(f"Character {char!r} is not in the alphabet")
        number = number * base + char_to_value[char]
    return number

