import re
import sys

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError("s must be a string")

    # Determine platform
    if platform == 'this':
        plat = 0 if sys.platform.startswith('win') else 1
    elif platform in (0, 1):
        plat = platform
    else:
        raise ValueError("platform must be 'this', 0, or 1")

    if not s:
        return []

    if plat == 1:  # POSIX-like
        # Handle quotes and escapes
        result = []
        i = 0
        n = len(s)
        current = []
        while i < n:
            c = s[i]
            if c in (' ', '\t', '\n', '\r', '\v', '\f'):
                if current:
                    result.append(''.join(current))
                    current = []
                i += 1
            elif c == '\\':
                if i + 1 < n:
                    current.append(s[i+1])
                    i += 2
                else:
                    current.append('\\')
                    i += 1
            elif c == "'":
                i += 1
                start = i
                while i < n and s[i] != "'":
                    i += 1
                if i < n:
                    current.append(s[start:i])
                    i += 1
                else:
                    current.append(s[start:])
            elif c == '"':
                i += 1
                start = i
                while i < n:
                    if s[i] == '\\':
                        if i + 1 < n and s[i+1] in ('"', '\\', '$', '`'):
                            current.append(s[i+1])
                            i += 2
                        else:
                            i += 1
                    elif s[i] == '"':
                        break
                    else:
                        current.append(s[i])
                        i += 1
                if i < n:
                    i += 1
            else:
                current.append(c)
                i += 1
        if current:
            result.append(''.join(current))
        return result
    else:  # Windows/CMD
        # Simplified: split on spaces, respect quotes
        result = []
        current = []
        in_quote = False
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == '"':
                in_quote = not in_quote
                i += 1
            elif c in (' ', '\t') and not in_quote:
                if current:
                    result.append(''.join(current))
                    current = []
                i += 1
            else:
                if c == '^' and i + 1 < n:
                    current.append(s[i+1])
                    i += 2
                else:
                    current.append(c)
                    i += 1
        if current:
            result.append(''.join(current))
        return result
