    try:
        number = int(number_str)
    except ValueError:
        # Try float in case decimals are allowed (unlikely but safe)
        try:
            number = float(number_str)
        except ValueError:
            raise ValueError(f"Invalid number in frequency: {number_str}")

    unit = unit.lower().strip()

    # Handle singular and plural units
    if unit in ("second", "seconds", "secs"):
        return datetime.timedelta(seconds=number)
    elif unit in ("minute", "minutes", "mins"):
        return datetime.timedelta(minutes=number)
    elif unit in ("hour", "hours", "hrs"):
        return datetime.timedelta(hours=number)
    elif unit in ("day", "days"):
        return datetime.timedelta(days=number)
    elif unit in ("week", "weeks", "wks"):
        return datetime.timedelta(weeks=number)
    else:
        raise ValueError(f"Unknown time unit: {unit}")

