def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    if not image_href or not isinstance(image_href, str):
        raise ValueError("Image href must be a non-empty string")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as e:
        raise ValueError(f"Failed to parse image href: {e}")

    # Use secure flag if parsed.scheme is not 'http' (covers https, ftps, etc.)
    use_ssl = parsed.scheme != 'http'

    # Extract netloc
    if not parsed.netloc:
        raise ValueError(f"Invalid image href: missing netloc in {image_href}")
    else:
        netloc = parsed.netloc

    # Extract image_id from path
    if parsed.path == "/" or not parsed.path:
        empty_id = f"{netloc}-"
        return empty_id, netloc, use_ssl
    else:
        image_id = parsed.path.lstrip('/').replace('/', '-')
        return image_id, netloc, use_ssl

