def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    elif isinstance(obj, bytes):
        return obj
    else:
        # If obj is not a string or bytes, we might want to raise an exception
        # or convert it to string first then encode.
        # Based on the docstring, it seems to imply that if it's a string, return bytes.
        # It doesn't specify behavior for other types, so it's safer to handle common cases.
        # If we just return, it might violate the expectation of returning bytes for a string.
        # Let's assume that for non-string/non-bytes, we either raise an exception or convert to string.
        # Given the function name "force_string", it might be more robust to just str() it.
        # However, the docstring says "in case it is a string", which implies a conditional.
        # Let's stick to the most straightforward interpretation: if str, encode; if bytes, return; else, raise or str.
        # To be safe and general, let's convert to string first if it's not bytes.
        try:
            s = str(obj)
            return s.encode('utf-8')
        except Exception as e:
            return "ERROR: {}".format(e).encode('utf-8')
