def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)

    if bufsize is None:
        bufsize = 1024

    # Try to read a chunk first to determine the type
    seq_bytes = seq.read(bufsize) if hasattr(seq, 'read') else seq

    # Determine the type based on the bytes
    if isinstance(seq_bytes, bytes):
        if seq_bytes.startswith(b'\xd0\xcf\x11\xe0'):
            seq_type = 'olefile'
        elif seq_bytes.startswith(b'\x1f\x8b'):
            seq_type = 'gzip'
        elif seq_bytes.startswith(b'PK\x03\x04'):
            seq_type = 'zip'
        elif seq_bytes.startswith(b'BEGIN '):
            seq_type = 'text'
        else:
            seq_type = 'binary'
    else:
        seq_type = type(seq).__name__

    # Create a sequence-like object that can be read multiple times
    class _SequenceWrapper:
        def __init__(self, data, original):
            self._data = data
            self._original = original
            self._pos = 0

        def read(self, size=-1):
            if size == -1:
                result = self._data[self._pos:]
                self._pos = len(self._data)
                return result
            else:
                result = self._data[self._pos:self._pos + size]
                self._pos += len(result)
                return result

        def seek(self, pos, whence=0):
            import io
            if whence == 0:
                self._pos = pos
            elif whence == 1:
                self._pos += pos
            elif whence == 2:
                self._pos = len(self._data) + pos
            else:
                raise ValueError("Invalid whence value")
            if self._pos < 0:
                raise io.UnsupportedOperation('negative seek')

        def tell(self):
            return self._pos

        def __len__(self):
            return len(self._data)

    if hasattr(seq, 'read'):
        full_data = seq.read()
        wrapper = _SequenceWrapper(full_data, seq)
    else:
        wrapper = seq

    return wrapper, seq_type
