def identify_request(request: RequestType):
    """
    Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if not hasattr(request, 'payload') or request.payload is None:
        return RequestType.UNKNOWN

    payload = request.payload
    if not isinstance(payload, dict):
        return RequestType.UNKNOWN

    # Try public message
    if 'public_message' in payload:
        public_message = payload['public_message']
        if isinstance(public_message, dict) and 'text' in public_message:
            return RequestType.PUBLIC_MESSAGE

    # Try private message
    if 'private_message' in payload:
        private_message = payload['private_message']
        if isinstance(private_message, dict) and 'text' in private_message:
            return RequestType.PRIVATE_MESSAGE

    # Check if legacy payload
    if 'legacy' in payload or 'legacy_payload' in payload:
        return RequestType.LEGACY

    # Fallback
    return RequestType.UNKNOWN

