def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    if not text:
        return tags, text

    # Find all tags with the pattern #tagname (followed by alphanumerics and underscores)
    tag_pattern = re.compile(r'#([a-zA-Z0-9_]+)')

    # Find all code blocks (between ``` and ``` or between ` and `)
    code_block_pattern = re.compile(r'```[\s\S]*?```|`[^`]*`')

    # Create a masked version of the text where code blocks are replaced with placeholders
    placeholder = '\x00'
    positions = []

    def replace_code_block(match):
        positions.append(match.start())
        return placeholder * len(match.group())

    masked_text = code_block_pattern.sub(replace_code_block, text)

    # Find tags in the masked text
    for match in tag_pattern.finditer(masked_text):
        tag = match.group(1)
        tags.add(tag)

    # If a replacer is provided, replace tags in the original text
    if replacer:
        def replace_tag(match):
            tag = match.group(1)
            # Only replace if not in a code block
            start = match.start()
            # Check if this position is in a code block
            in_code_block = False
            for pos in positions:
                # We need to reconstruct which code blocks contain this position
                # Let's use a different approach: check the original text for code blocks
                pass

            # Better approach: check if the tag in the original text is within a code block
            # Find the code block that contains this position
            end = match.end()
            for cb_match in code_block_pattern.finditer(text):
                if cb_match.start() <= start and end <= cb_match.end():
                    in_code_block = True
                    break

            if not in_code_block:
                return replacer(tag)
            return match.group(0)

        new_text = tag_pattern.sub(replace_tag, text)
    else:
        new_text = text

    return tags, new_text

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False

    # A tag must be non-empty
    if not tag:
        return False

    # A tag can only contain alphanumeric characters, spaces, and hyphens
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 -")
    if any(c not in allowed_chars for c in tag):
        return False

    # Should not have multiple consecutive spaces
    if "  " in tag:
        return False

    # Should not start or end with a space or hyphen
    if tag[0] in " -" or tag[-1] in " -":
        return False

    # Should not have consecutive hyphens
    if "--" in tag:
        return False

