def xml_children_as_dict(node):
    """
    Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        tag = child.tag
        if tag not in result:
            result[tag] = []
        result[tag].append(child)
    # if the list for each tag has only one element, use the element itself, not the list
    for tag, elements in list(result.items()):
        if len(elements) == 1:
            result[tag] = elements[0]
    return result
