def parse_diaspora_webfinger(document: str) -> Dict:
    result = {}
    # Handle JSON format (with or without "webfinger" wrapper)
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            # JSON format may be directly the webfinger object or wrapped
            data = data if isinstance(data.get("links", None), list) else data.get("webfinger", data)
            if isinstance(data, dict) and "links" in data:
                result["links"] = data["links"]
                subject = data.get("subject")
                if subject:
                    result["subject"] = subject
                return result
    except (json.JSONDecodeError, TypeError):
        pass
    # Handle XRD format
    data = None
    try:
        data = xmltodict.parse(document)
    except Exception:
        data = None
    if data is not None and isinstance(data, dict) and "XRD" in data:
        xrd = data.get("XRD", {})
        result_links = []
        aliased = xrd.get("Alias")
        if aliased:
            if not isinstance(aliased, list):
                aliased = [aliased]
            for item in aliased:
                if isinstance(item, dict) or (isinstance(item, str) or item is None):
                    entry = {
                        "link": item if isinstance(item, str) else item.get("$", item) if isinstance(item, dict) else None
                    }
                    # Preserve original attribute info
                    result_links.append(item if isinstance(item, dict) else {"link": item})
        props = xrd.get("Property")
        if props and isinstance(props, list):
            for prop in props:
                if isinstance(prop, dict):
                    value = prop.get("$")
                    link = prop.get("value")
                    if isinstance(value, dict):
                        link = value
                    result_links.append(link)
        if props and (not isinstance(props, list)):
            single = props.get("value", props)
            if isinstance(props, dict) and "value" not in props and isinstance(props.get("$"), dict):
                single = props["$"]
            if single is not None:
                result_links.append(single)
        result["links"] = result_links
        return result
    return result

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    import requests
    try:
        if method.lower() == "get":
            response = requests.get(url, timeout=timeout, *args, **kwargs)
        elif method.lower() == "put":
            response = requests.put(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "delete":
            response = requests.delete(url, timeout=timeout, *args, **kwargs)
        elif method.lower() == "patch":
            response = requests.patch(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() in ("post", "request"):
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return response.status_code, None
    except Exception as e:
        return None, e

