def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    try:
        # Retrieve the spec from self, assuming it exists
        spec = getattr(self, 'spec', None)
        if spec is None:
            raise AttributeError("No spec attribute found on the object.")

        # Initialize an empty dictionary to store the resolved defaults
        defaults = {}

        # Iterate through the spec and extract default values
        for arg_name, arg_spec in spec.items():
            # Check if the arg_spec is a dictionary containing a 'default' key
            if isinstance(arg_spec, dict) and 'default' in arg_spec:
                defaults[arg_name] = arg_spec['default']
            # If arg_spec has a get_default method, call it
            elif hasattr(arg_spec, 'get_default'):
                defaults[arg_name] = arg_spec.get_default()
            # Otherwise, leave the default as None or omit
            else:
                defaults[arg_name] = None

        return defaults
    except Exception as e:
        # Log the exception if necessary, and re-raise or return a fallback
        print(f"Error while resolving spec defaults: {str(e)}")
        raise
