def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    invalid_args = []
    for arg_name, arg_value in args.items():
        # Get the argument definition from the parent class's _actions list
        arg_definition = None
        for action in self._actions:
            if action.dest == arg_name:
                arg_definition = action
                break

        # If the argument is not in the actions list, it might be an
        # unrecognized argument or an argument that doesn't need validation
        if arg_definition is None:
            continue

        # If the argument specifies choices, validate the value
        if arg_definition.choices is not None:
            if isinstance(arg_value, list):
                # For list arguments, validate each item in the list
                for item in arg_value:
                    if item not in arg_definition.choices:
                        raise ValueError(
                            f"invalid choice: {item!r} (choose from {[str(c) for c in arg_definition.choices]})"
                        )
            else:
                # For single value arguments
                if arg_value not in arg_definition.choices:
                    raise ValueError(
                        f"invalid choice: {arg_value!r} (choose from {[str(c) for c in arg_definition.choices]})"
                    )

