@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        extra_vars = []

    for extra_var in extra_vars:
        if extra_var is None:
            continue
        if isinstance(extra_var, dict):
            vars_dict.update(extra_var)
        elif isinstance(extra_var, str):
            # Assume extra-vars in list are key=value strings
            if '=' in extra_var:
                key, value = extra_var.split('=', 1)
                vars_dict[key] = value
            else:
                # Handle boolean flags
                vars_dict[extra_var] = True
        elif hasattr(extra_var, 'items') and callable(getattr(extra_var, 'items', None)):
            # Fallback for dict-like objects
            for k, v in extra_var.items():
                vars_dict[k] = v
