def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    import subprocess
    import shlex
    import logging

    logger = logging.getLogger(__name__)

    # Build the command
    cmd = ["ansible-playbook"]

    # Add verbose flags
    if verbose is not None:
        try:
            verbose_int = int(verbose)
        except (ValueError, TypeError):
            verbose_int = 0
        # Convert verbose level to -v flags
        for _ in range(verbose_int):
            cmd.append("-v")

    # Add extra variables
    if extra_vars:
        if isinstance(extra_vars, dict):
            for key, value in extra_vars.items():
                cmd.extend(["-e", f"{key}={value}"])
        else:
            # If not dict, just append as is (might be a string or list)
            if isinstance(extra_vars, str):
                cmd.extend(["-e", extra_vars])
            elif isinstance(extra_vars, list):
                for item in extra_vars:
                    cmd.extend(["-e", item])

    # Add playbook path
    cmd.append(playbook_path)

    # Add additional ansible arguments
    if ansible_args and isinstance(ansible_args, dict):
        for key, value in ansible_args.items():
            # Build --key=value or --key value based on convention
            # Typically args are like "--limit", "--tags", etc.
            # For boolean flags, value might be True/None
            if value is None:
                cmd.append(f"--{key}")
            elif isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
            else:
                cmd.extend([f"--{key}", str(value)])

    # Build environment or check workspace for environment
    logger.debug(f"Executing command: {' '.join(cmd)}")

    try:
        result = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            universal_newlines=True
        )

        # Return the result or appropriate value based on typical ansible_playbook wrapper behavior
        # Usually returns the return code or an object with stdout/stderr
        # Since the function signature doesn't specify return type, we return the CompletedProcess
        # or a dictionary. Let's return a tuple (returncode, stdout, stderr) or the result object.
        # Looking at typical patterns, let's return the result object or just the stdout.
        # Given the lack of specific return requirements, returning the completed process is reasonable.
        # However, many such functions return the return code. Let's return the return code.
        if result.returncode != 0:
            logger.error(f"ansible-playbook failed with return code {result.returncode}\n{result.stderr}")
        else:
            logger.info(f"ansible-playbook succeeded\n{result.stdout}")

        return result.returncode

    except FileNotFoundError:
        logger.error("ansible-playbook command not found. Please ensure Ansible is installed.")
        raise
    except Exception as e:
        logger.error(f"Error executing ansible-playbook: {e}")
        raise
