def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    for key, value in values_dict.items():
        if value is None:
            continue

        # If the value is already a non-string type, leave it as is
        if not isinstance(value, str):
            continue

        # Convert string representations of common scalar types
        try:
            # Try integers first
            if value.isdigit() or (value.startswith('-') and value[1:].isdigit()):
                values_dict[key] = int(value)
            # Then try floats
            elif '.' in value and all(c.isdigit() or c in ('.', '-', '+') for c in value if c not in ('.', '-', '+', 'e', 'E')):
                values_dict[key] = float(value)
            # Special case for boolean 'true'/'false' (case-insensitive)
            elif value.lower() in ('true', 'false'):
                values_dict[key] = value.lower() == 'true'
            else:
                # Keep as string
                values_dict[key] = value
        except (ValueError, TypeError):
            # If conversion fails, leave as original string
            values_dict[key] = value

