def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import logging

    spec_file = os.path.join(plugin_dir, 'plugin_spec.json')
    flat_dict = {}

    try:
        with open(spec_file, 'r') as f:
            spec_dict = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        logging.warning(f"Could not read plugin spec for {plugin_dir}: {e}")
        return flat_dict

    def flatten_dict(data, prefix=''):
        result = {}
        for key, value in data.items():
            new_key = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                result.update(flatten_dict(value, new_key))
            elif isinstance(value, list):
                result[new_key] = json.dumps(value)
            else:
                result[new_key] = value
        return result

    flat_dict = flatten_dict(spec_dict)
    return flat_dict
