def strip_root(path, root):
    if not root or not path:
        raise ValueError("Both path and root must be non-empty strings")

    if len(root) > len(path):
        raise ValueError("Root is longer than path")

    if not path.startswith(root):
        raise ValueError("Path does not start with root")

    # Remove the root from path
    stripped_path = path[len(root):]

    # Handle the case where root ends with a separator
    if root[-1] in ('/', '\\'):
        return stripped_path
    else:
        # If there's a separator immediately after the root, remove it
        if stripped_path and stripped_path[0] in ('/', '\\'):
            return stripped_path[1:]
        else:
            return stripped_path
